import pyomo.environ as pyo

DATA = {
    "gifts_per_trip": {0: 50, 1: 70},      # new, old
    "diesel_per_trip": {0: 30, 1: 40},     # new, old
    "min_gifts": 1000,
    "max_new_trips": 15,
    "min_old_share": 0.4,
    "companies": [0, 1],
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.C = pyo.Set(initialize=d["companies"], ordered=True)

    # Variables: integer number of trips per company
    def x_bounds(m, c):
        if c == 0:
            return (0, d["max_new_trips"])
        return (0, None)

    model.x = pyo.Var(model.C, within=pyo.NonNegativeIntegers, bounds=x_bounds)

    # Objective: minimize total diesel
    def obj_rule(m):
        return sum(d["diesel_per_trip"][c] * m.x[c] for c in m.C)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraint: deliver at least min_gifts (>=)
    def gifts_rule(m):
        return sum(d["gifts_per_trip"][c] * m.x[c] for c in m.C) >= d["min_gifts"]

    model.gifts = pyo.Constraint(rule=gifts_rule)

    # Constraint: new company trip cap (<=) — also in bounds, kept explicit
    def new_cap_rule(m):
        return m.x[0] <= d["max_new_trips"]

    model.new_cap = pyo.Constraint(rule=new_cap_rule)

    # Constraint: at least 40% of trips by old company
    # x[1] >= 0.4*(x[0]+x[1])  ->  (1-0.4)*x[1] - 0.4*x[0] >= 0
    def old_share_rule(m):
        s = d["min_old_share"]
        return (1 - s) * m.x[1] - s * m.x[0] >= 0

    model.old_share = pyo.Constraint(rule=old_share_rule)

    return model


